import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Buffer } from '@/modules/order-management/buffer/buffer.entity';
import { CreateBufferCommand } from '@/modules/order-management/buffer/commands/create-buffer.command';

@CommandHandler(CreateBufferCommand)
export class CreateBufferHandler
  implements ICommandHandler<CreateBufferCommand>
{
  public constructor(
    @InjectRepository(Buffer)
    private readonly bufferRepo: Repository<Buffer>,
  ) {}

  public async execute(command: CreateBufferCommand): Promise<Buffer> {
    const { dto } = command;

    const entity = this.bufferRepo.create({
      ...dto,
    });

    return this.bufferRepo.save(entity);
  }
}

import { NotFoundException } from '@nestjs/common';
import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Buffer } from '@/modules/order-management/buffer/buffer.entity';
import { DeleteBufferCommand } from '@/modules/order-management/buffer/commands/delete-buffer.command';

@CommandHandler(DeleteBufferCommand)
export class DeleteBufferHandler
  implements ICommandHandler<DeleteBufferCommand>
{
  public constructor(
    @InjectRepository(Buffer)
    private readonly bufferRepo: Repository<Buffer>,
  ) {}

  public async execute(command: DeleteBufferCommand): Promise<Buffer> {
    const { plant, id } = command;

    const entity = await this.bufferRepo.findOne({
      where: { plant, id },
    });

    if (!entity) {
      throw new NotFoundException(
        `Buffer order ${id} at plant ${plant} not found`,
      );
    }

    return this.bufferRepo.remove(entity);
  }
}

import { NotFoundException } from '@nestjs/common';
import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
