import { UpdateBufferCommand } from '@/modules/order-management/buffer/commands/update-buffer.command';

@CommandHandler(UpdateBufferCommand)
export class UpdateBufferHandler
  implements ICommandHandler<UpdateBufferCommand>
{
  public constructor(
    @InjectRepository(Buffer)
    private readonly bufferRepo: Repository<Buffer>,
  ) {}

  public async execute(command: UpdateBufferCommand): Promise<Buffer> {
    const { plant, id, dto } = command;

    const entity = await this.bufferRepo.findOne({
      where: { plant, id },
    });

    if (!entity) {
      throw new NotFoundException(
        `Buffer order ${id} at plant ${plant} not found`,
      );
    }

    Object.assign(entity, dto);

    return this.bufferRepo.save(entity);
  }
}

