import { IQueryHandler, QueryHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Buffer } from '@/modules/order-management/buffer/buffer.entity';
import { MesBufferDto } from '@/modules/order-management/buffer/dtos/mes-buffer.dto';
import { FindWksByPlantAndWorkcenterQuery } from '@/modules/order-management/buffer/queries/find-wk-by-plant-and-workcenter.query';

@QueryHandler(FindWksByPlantAndWorkcenterQuery)
export class FindWksByPlantAndWorkcenterHandler
  implements IQueryHandler<FindWksByPlantAndWorkcenterQuery>
{
  public constructor(
    @InjectRepository(Buffer)
    private readonly repo: Repository<Buffer>,
  ) {}

  public async execute(query: FindWksByPlantAndWorkcenterQuery): Promise<{
    data: Array<MesBufferDto>;
    total: number;
    page: number;
    limit: number;
  }> {
    const { plant, workcenters, page } = query;
    const limit = Number.parseInt(process.env.MES_BUFFER_LIMIT ?? '10', 10);

    const qb = this.repo.createQueryBuilder('mb');
    qb.select([
      'mb.plant',
      'mb.orderId',
      'mb.materialNumber',
      'mb.upstreamMaterial',
      'mb.workcenter',
      'mb.tpaNumber',
      'mb.deliveryNumber',
      'mb.startPickingDatetime',
      'mb.endPickingDatetime',
      'mb.quantity',
      'mb.customer',
      'mb.productionLineUpstream',
      'mb.sourceLocation',
      'mb.destinationLocation',
      'mb.bufferStatus',
      'mb.batch',
      'mb.batchTest',
      'mb.calendarType1',
      'mb.calendarType2',
      'mb.calendarType3',
      'mb.calendarType4',
      'mb.calendarType5',
      'mb.calendarType6',
      'mb.endPreparationDatetime',
      'mb.truckDepartureDatetime',
      'mb.launchDatetime',
      'mb.startProductionDatetime',
      'mb.endProductionDatetime',
    ]);

    qb.where('mb.plant = :plant', { plant });

    if (workcenters?.length > 0) {
      qb.andWhere('mb.workcenter IN (:...workcenters)', { workcenters });
    }

    const skip = (page - 1) * limit;
    qb.skip(skip).take(limit);

    const [data, total] = await qb.getManyAndCount();

    return { data, total, page, limit };
  }
}

