import { InternalServerErrorException } from '@nestjs/common';
import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CreateProductionOrderCommand } from '@/modules/order-management/production-order/commands/create-production-order.command';
import { ProductionOrder } from '@/modules/order-management/production-order/production-order.entity';

@CommandHandler(CreateProductionOrderCommand)
export class CreateProductionOrderHandler
  implements ICommandHandler<CreateProductionOrderCommand>
{
  public constructor(
    @InjectRepository(ProductionOrder)
    private readonly productionOrderRepo: Repository<ProductionOrder>,
  ) {}

  public async execute(
    command: CreateProductionOrderCommand,
  ): Promise<ProductionOrder | null> {
    const { dto } = command;

    const entity = this.productionOrderRepo.create({
      ...dto,
    });

    try {
      await this.productionOrderRepo.insert(entity);
    } catch (error) {
      throw new InternalServerErrorException(
        `Production order ${dto.productionOrderId} at plant ${dto.plant} could not be created: ${error}`,
      );
    }

    return entity;
  }
}

