import {
  BadRequestException,
  InternalServerErrorException,
} from '@nestjs/common';
import { IQueryHandler, QueryHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { GetOrderStatusResponseDto } from '@/modules/order-management/production-order/dtos/get-order-status-response.dto';
import { ProductionOrder } from '@/modules/order-management/production-order/production-order.entity';
import { GetOrderStatusQuery } from '@/modules/order-management/production-order/queries/get-order-status.query';

@QueryHandler(GetOrderStatusQuery)
export class GetOrderStatusHandler
  implements IQueryHandler<GetOrderStatusQuery>
{
  public constructor(
    @InjectRepository(ProductionOrder)
    private readonly orderRepository: Repository<ProductionOrder>,
  ) {}

  public async execute(
    query: GetOrderStatusQuery,
  ): Promise<GetOrderStatusResponseDto> {
    try {
      const { plant, page, filters } = query;

      if (!plant) {
        throw new BadRequestException('The "plant" parameter is required.');
      }

      const limit = Number.parseInt(process.env.MES_BUFFER_LIMIT ?? '10', 10);
      const skip = (page - 1) * limit;

      const qb = this.orderRepository
        .createQueryBuilder('o')
        .where('o.plant = :plant', { plant });

      if (filters) {
        if (Array.isArray(filters.orderId) && filters.orderId.length > 0) {
          qb.andWhere('o.production_order_id IN (:...orderIds)', {
            orderIds: filters.orderId,
          });
        }

        if (
          Array.isArray(filters.materialNumber) &&
          filters.materialNumber.length > 0
        ) {
          qb.andWhere('o.material_id IN (:...materials)', {
            materials: filters.materialNumber,
          });
        }

        if (
          Array.isArray(filters.workcenter) &&
          filters.workcenter.length > 0
        ) {
          qb.andWhere('o.workcenter_id IN (:...workcenters)', {
            workcenters: filters.workcenter,
          });
        }

        if (Array.isArray(filters.resource) && filters.resource.length > 0) {
          qb.andWhere('o.resource_id IN (:...resources)', {
            resources: filters.resource,
          });
        }
      }

      const [records, totalRecords] = await qb
        .skip(skip)
        .take(limit)
        .getManyAndCount();

      const totalPages = Math.ceil(totalRecords / limit);

      const result: GetOrderStatusResponseDto = {
        page,
        totalPages,
        totalRecords,
        orders: records.map((o) => ({
          plantId: o.plant,
          orderId: o.productionOrderId,
          materialNumber: o.materialId,
          orderedQuantity: o.orderedQuantity,
          producedQuantity: o.quantityDone ?? 0,
          groupingKey: o.groupingKey,
          workcenter: o.workcenterId,
          resource: o.resourceId,
          sequenceNumber: o.sequenceNumber,
          isFrozen: !!o.isFrozen,
          linkedWK: o.linkedPickingOrderId,
          status: o.status,
        })),
      };

      return result;
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }
      console.error('Error fetching orders:', error);
      throw new InternalServerErrorException(
        'An unexpected error occurred while fetching orders.',
      );
    }
  }
}

import { NotFoundException } from '@nestjs/common';
import { IQueryHandler, QueryHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { ProductionOrder } from '@/modules/order-management/production-order/production-order.entity';
import { GetProductionOrderQuery } from '@/modules/order-management/production-order/queries/get-production-order.query';

@QueryHandler(GetProductionOrderQuery)
export class GetProductionOrderHandler
  implements IQueryHandler<GetProductionOrderQuery>
{
  public constructor(
    @InjectRepository(ProductionOrder)
    private readonly repo: Repository<ProductionOrder>,
  ) {}

  public async execute(
    query: GetProductionOrderQuery,
  ): Promise<ProductionOrder | null> {
    const { plant, productionOrderId } = query;
    const entity = await this.repo.findOne({
      where: { plant, productionOrderId },
    });

    if (!entity) {
      throw new NotFoundException(
        `Production order ${productionOrderId} at plant ${plant} not found`,
      );
    }

    return entity;
  }
}

import { Controller, Get, HttpException, HttpStatus } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { MssqlDatabaseChecker } from '@/providers/database/mssql/mssql.database.checker';

@Controller('probes')
export class ProbesController {
  private readonly healthMessage = 'mesx/order-management-api [OK]';

  private readonly logger: AppLogger = new AppLogger(ProbesController.name);

  public constructor(private readonly databaseChecker: MssqlDatabaseChecker) {}

  @Get('health')
  public getHello(): string {
    return this.healthMessage;
  }

  @Get('startup')
  public async isApplicationStartedUp(): Promise<string> {
    const isPendingMigrations = await this.databaseChecker.pendingMigrations();

    if (isPendingMigrations) {
      this.logger.log('Startup Probe: Migrations are still pending');
      throw new HttpException(
        'Migrations are still pending',
        HttpStatus.SERVICE_UNAVAILABLE,
      );
    }

    this.logger.log('Startup Probe: Migrations Applied [OK]');
    return 'Migrations Applied [OK]';
  }
}

