@ApiTags('routings')
@Controller('routings')
@UseFilters(MesGenericErrorFilter)
export class RoutingsController {
  public constructor(private readonly service: RoutingsService) {}

  @Get()
  @ApiOperation({ summary: 'Retrieve all routings for a plant' })
  @ApiQuery({
    name: 'plant',
    required: true,
    description: 'Plant id to filter routings',
    type: 'number',
    example: 1146,
  })
  @ApiResponse({
    status: 200,
    description: 'List of routings',
    type: [Routing],
  })
