  @ApiOperation({ summary: 'Delete a routing' })
  @ApiParam({ name: 'id', required: true, description: 'Routing id' })
  @ApiNoContentResponse({ description: 'Routing deleted' })
  @ApiBadRequestResponse({
    description: 'Cannot delete routing in use or linked to released orders',
