    @Param('id', ParseIntPipe) id: number,
    @Query('plant') plant: number,
  ): Promise<{ assigned: Array<MaterialDtl>; available: Array<MaterialDtl> }> {
    return this.service.listMaterials(id, Number(plant));
  }

  @Post(':id/materials')
  @ApiOperation({ summary: 'Assign a material to routing' })
  @ApiParam({ name: 'id', required: true, description: 'Routing id' })
  @ApiCreatedResponse({
    description: 'Material assigned to routing',
    type: MaterialDtl,
  })
  @ApiBadRequestResponse({ description: 'Invalid request or routing in use' })
  @ApiConflictResponse({
    description: 'Material already assigned to this routing',
  })
  @ApiBody({ type: AssignMaterialBodyDto })
  public async assignMaterial(
    @Param('id', ParseIntPipe) id: number,
    @Body() dto: AssignMaterialBodyDto,
  ): Promise<MaterialDtl> {
    return this.service.assignMaterial(id, dto);
  }

  @Put(':id/materials/:materialId')
  @ApiOperation({ summary: 'Unassign a material from routing' })
  @ApiParam({ name: 'id', required: true, description: 'Routing id' })
  @ApiParam({ name: 'materialId', required: true, description: 'Material id' })
