  @Post(':id/operations')
  @ApiOperation({ summary: 'Add operation to routing' })
  @ApiParam({ name: 'id', required: true, description: 'Routing id' })
  @ApiCreatedResponse({
    description: 'Operation added',
    type: RoutingOperation,
  })
  @ApiBadRequestResponse({ description: 'Invalid payload or routing in use' })
