  public async createOperation(
    @Param('id', ParseIntPipe) id: number,
    @Body() dto: CreateOperationDto,
  ): Promise<RoutingOperation> {
    return this.service.createOperation({ ...dto, routingId: id });
  }

  @Put(':id/operations/:opId')
  @ApiOperation({ summary: 'Update an operation' })
  @ApiParam({ name: 'id', required: true, description: 'Routing id' })
  @ApiParam({ name: 'opId', required: true, description: 'Operation id' })
  @ApiResponse({
    status: 200,
    description: 'Updated operation',
    type: RoutingOperation,
  })
  @ApiBadRequestResponse({
    description:
      'Cannot modify operation when routing is in use or invalid payload',
  })
  @ApiNotFoundResponse({ description: 'Operation not found' })
  @ApiBody({ type: UpdateOperationDto })
  public async updateOperation(
    @Param('id', ParseIntPipe) id: number,
    @Param('opId', ParseIntPipe) opId: number,
    @Body() dto: UpdateOperationDto,
  ): Promise<RoutingOperation> {
    return this.service.updateOperation(opId, dto);
  }

  @Delete(':id/operations/:opId')
  @ApiOperation({ summary: 'Delete an operation' })
  @ApiParam({ name: 'id', required: true, description: 'Routing id' })
  @ApiParam({ name: 'opId', required: true, description: 'Operation id' })
  @ApiNoContentResponse({ description: 'Operation deleted' })
  @ApiBadRequestResponse({
    description: 'Cannot delete operation when routing is in use',
  })
  @HttpCode(HttpStatus.NO_CONTENT)
  public async deleteOperation(
    @Param('id', ParseIntPipe) id: number,
    @Param('opId', ParseIntPipe) opId: number,
  ): Promise<void> {
    await this.service.removeOperation(id, opId);
  }

  @Post(':id/operations/reorder')
  @ApiOperation({ summary: 'Reorder operations' })
  @ApiParam({ name: 'id', required: true, description: 'Routing id' })
