    status: 200,
    description: 'Updated operations sequence',
    type: [RoutingOperation],
  })
  @ApiBadRequestResponse({ description: 'Invalid sequence or length mismatch' })
  public async reorderOperations(
    @Param('id', ParseIntPipe) id: number,
    @Body() body: { routingOperationIds: Array<number> },
  ): Promise<Array<RoutingOperation>> {
    return this.service.reorderOperations(id, body.routingOperationIds);
  }
}

