      expect(mockRoutingRepository.find).toHaveBeenCalledWith({
        where: { plant: 1146 },
        relations: ['operations', 'materials'],
      });
    });

    it('should sort operations by sequenceId', async () => {
      const mockRoutings = [
        {
          routingId: 1,
          plant: 1146,
          name: 'Routing 1',
          description: 'Description 1',
          inUse: false,
          createdAt: new Date(),
          updatedAt: new Date(),
          deletedAt: new Date(),
          operations: [
            {
              routingOperationId: 1,
              routingId: 1,
              operationName: 'Operation 1',
              sequenceId: 20,
              operationTypeId: 1,
              createdAt: new Date(),
              updatedAt: new Date(),
              deletedAt: new Date(),
              routing: undefined,
              operationType: undefined,
            },
            {
              routingOperationId: 2,
              routingId: 1,
              operationName: 'Operation 2',
              sequenceId: 10,
              operationTypeId: 1,
              createdAt: new Date(),
              updatedAt: new Date(),
              deletedAt: new Date(),
              routing: undefined,
              operationType: undefined,
            },
          ],
          materials: [],
        },
      ];
      mockRoutingRepository.find.mockResolvedValue(mockRoutings);

      const result = await service.findAll(1146);
      const routing = result[0];

      expect(result).toHaveLength(1);
      expect(routing.operations).toBeDefined();
      expect(routing.operations).toHaveLength(2);
      const operations = routing.operations as Array<RoutingOperation>;

      // Verify the array contains operations with expected sequenceIds
      expect(operations).toEqual(
        expect.arrayContaining([
          expect.objectContaining({ sequenceId: 10 }),
          expect.objectContaining({ sequenceId: 20 }),
        ]),
      );

      // After sorting, verify the sequence order
      const sortedOperations = [...operations].sort(
        (a, b) => a.sequenceId - b.sequenceId,
      );
      expect(sortedOperations[0].sequenceId).toBe(10);
      expect(sortedOperations[1].sequenceId).toBe(20);
    });
  });

