      mockRoutingRepository.findOne.mockResolvedValue(null);
      mockRoutingRepository.create.mockReturnValue(mockRouting);
      mockRoutingRepository.save.mockResolvedValue(mockRouting);

      const result = await service.create(createRoutingDto);
      expect(result).toEqual(mockRouting);
    });

    it('should throw ConflictException if routing name exists for plant', async () => {
      const createRoutingDto: CreateRoutingDto = {
        name: 'Test Routing',
        plant: 1146,
        description: 'Test Description',
      };
      mockRoutingRepository.findOne.mockResolvedValue({ routingId: 1 });

      await expect(service.create(createRoutingDto)).rejects.toThrow(
        ConflictException,
      );
    });
  });

  describe('update', () => {
    it('should update an existing routing', async () => {
      const updateRoutingDto: UpdateRoutingDto = {
        name: 'Updated Routing',
        description: 'Updated Description',
      };
      const existingRouting = {
        routingId: 1,
        plant: 1146,
        name: 'Original Routing',
      };
      const updatedRouting = {
        ...existingRouting,
        ...updateRoutingDto,
      };

      mockRoutingRepository.findOne.mockResolvedValueOnce(existingRouting);
      mockRoutingRepository.findOne.mockResolvedValueOnce(existingRouting);
      mockRoutingRepository.save.mockResolvedValue(updatedRouting);

      const result = await service.update(1, updateRoutingDto);
      expect(result).toEqual(updatedRouting);
      expect(result.plant).toBe(1146); // Plant should be preserved
    });

    it('should throw NotFoundException if routing not found', async () => {
      mockRoutingRepository.findOne.mockResolvedValue(null);

      await expect(service.update(1, { name: 'Updated' })).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('remove', () => {
    it('should remove a routing if not in use', async () => {
      const mockRouting = {
        routingId: 1,
        plant: 1146,
        inUse: false,
      };
      mockRoutingRepository.findOne.mockResolvedValueOnce(mockRouting);
      mockRoutingRepository.findOne.mockResolvedValueOnce(mockRouting);
      mockRoutingRepository.remove.mockResolvedValue(mockRouting);

      await expect(service.remove(1)).resolves.not.toThrow();
    });

    it('should throw BadRequestException if routing is in use', async () => {
      const mockRouting = {
        routingId: 1,
        plant: 1146,
        inUse: true,
      };
      mockRoutingRepository.findOne.mockResolvedValueOnce(mockRouting);
      mockRoutingRepository.findOne.mockResolvedValueOnce(mockRouting);

      await expect(service.remove(1)).rejects.toThrow(BadRequestException);
    });
  });
});

import {
  Injectable,
  NotFoundException,
  BadRequestException,
  ConflictException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { IsNull, Repository } from 'typeorm';
import { AssignMaterialBodyDto } from './dto/assign-material-body.dto';
import { CreateOperationDto } from './dto/create-operation.dto';
import { CreateRoutingDto } from './dto/create-routing.dto';
import { UpdateOperationDto } from './dto/update-operation.dto';
import { UpdateRoutingDto } from './dto/update-routing.dto';
import { MaterialDtl } from './entities/material-dtl.entity';
import { OperationType } from './entities/operation-type.entity';
import { RoutingOperation } from './entities/routing-operation.entity';
import { Routing } from './entities/routing.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class RoutingsService {
  private readonly logger = new AppLogger(RoutingsService.name);

  public constructor(
    @InjectRepository(Routing)
    private readonly routingRepo: Repository<Routing>,

    @InjectRepository(RoutingOperation)
    private readonly operationRepo: Repository<RoutingOperation>,

    @InjectRepository(MaterialDtl)
    private readonly materialRepo: Repository<MaterialDtl>,

    @InjectRepository(OperationType)
    private readonly operationTypeRepo: Repository<OperationType>,
  ) {}

  public async findAll(plant: number): Promise<Array<Routing>> {
    try {
      const routings = await this.routingRepo.find({
        where: { plant },
        relations: ['operations', 'materials'],
      });
      // Ensure operations are returned in sequence order
      for (const r of routings) {
        if (r.operations && r.operations.length > 1) {
          r.operations.sort(
            (a, b) => (a.sequenceId ?? 0) - (b.sequenceId ?? 0),
          );
        }
      }
      return routings;
    } catch (error) {
      this.logger.error(
        `findAll(plant: ${plant}) failed`,
        (error as Error).stack,
      );
      throw error;
    }
  }

  public async findOne(id: number, plant: number): Promise<Routing> {
    try {
      const routing = await this.routingRepo.findOne({
        where: { routingId: id, plant },
        relations: ['operations', 'materials'],
      });
      if (!routing) {
        throw new NotFoundException(
          `Routing ${id} not found for plant ${plant}`,
        );
      }
      return routing;
    } catch (error) {
      this.logger.error(
        `findOne(id: ${id}, plant: ${plant}) failed`,
        (error as Error).stack,
      );
      throw error;
    }
  }

  public async create(dto: CreateRoutingDto): Promise<Routing> {
    try {
      const exists = await this.routingRepo.findOne({
        where: { plant: dto.plant, name: dto.name },
      });
      if (exists) {
        throw new ConflictException(
          'Routing with the same name already exists for this plant',
        );
      }

      const entity = this.routingRepo.create({ ...dto });
      return await this.routingRepo.save(entity);
    } catch (error) {
      this.logger.error('create failed', (error as Error).stack);
      throw error;
    }
  }

  public async update(id: number, dto: UpdateRoutingDto): Promise<Routing> {
    try {
      // First get the current routing to get its plant
      const current = await this.routingRepo.findOne({
        where: { routingId: id },
      });

      if (!current) {
        throw new NotFoundException(`Routing ${id} not found`);
      }

      const routing = await this.findOne(id, current.plant);

      // Preserve the existing plant value and merge with the update DTO
      const updatedRouting = {
        ...routing,
        ...dto,
        plant: current.plant, // Ensure plant value is preserved
      };

      return await this.routingRepo.save(updatedRouting);
    } catch (error) {
      this.logger.error(`update(${id}) failed`, (error as Error).stack);
      throw error;
    }
  }

  public async remove(id: number): Promise<void> {
    try {
      // First get the current routing to get its plant
      const current = await this.routingRepo.findOne({
        where: { routingId: id },
      });

      if (!current) {
        throw new NotFoundException(`Routing ${id} not found`);
      }

      const routing = await this.findOne(id, current.plant);
      if (routing.inUse) {
        throw new BadRequestException('Cannot delete routing that is in use');
      }

      await this.routingRepo.remove(routing);
    } catch (error) {
      this.logger.error(`remove(${id}) failed`, (error as Error).stack);
      throw error;
    }
  }

  // Materials
  public async listMaterials(
    routingId: number,
    plant: number,
  ): Promise<{ assigned: Array<MaterialDtl>; available: Array<MaterialDtl> }> {
    try {
      const assigned = await this.materialRepo.find({
        where: { routingId, plant },
        relations: ['routing'],
      });
      const available = await this.materialRepo.find({
        where: { routingId: IsNull(), plant },
      });
      return { assigned, available };
    } catch (error) {
      this.logger.error(
        `listMaterials(${routingId},${plant}) failed`,
        (error as Error).stack,
      );
      throw error;
    }
  }

  public async assignMaterial(
    routingId: number,
    dto: AssignMaterialBodyDto,
  ): Promise<MaterialDtl> {
    try {
      // Get the routing with its plant
      const current = await this.routingRepo.findOne({
        where: { routingId },
      });

      if (!current) {
        throw new NotFoundException(`Routing ${routingId} not found`);
      }

      const routing = await this.findOne(routingId, current.plant);
      if (routing.inUse) {
        throw new BadRequestException(
          'Cannot assign material to a routing that is in use',
        );
      }
      const existing = await this.materialRepo.findOne({
        where: { plant: dto.plant, materialId: dto.materialId },
      });

      if (existing?.routingId === routingId) {
        throw new ConflictException(
          'Material already assigned to this routing',
        );
      }

      const toSave = {
        ...existing,
        plant: dto.plant,
        materialId: dto.materialId,
        routingId,
      } as MaterialDtl;
      return await this.materialRepo.save(toSave);
    } catch (error) {
      this.logger.error('assignMaterial failed', (error as Error).stack);
      throw error;
    }
  }

  public async unassignMaterial(
    plant: number,
    materialId: string,
  ): Promise<void> {
    try {
      // First check if material exists
      const existing = await this.materialRepo.findOne({
        where: { plant, materialId },
      });

      if (!existing) {
        throw new NotFoundException('Material not found');
      }

      // Execute raw SQL update
      await this.materialRepo.query(
        `UPDATE material_dtl SET routing_id = NULL WHERE plant = @0 AND material_id = @1`,
        [plant, materialId],
      );

      // Verify the update
      const verified = await this.materialRepo.findOne({
        where: { plant, materialId },
      });

      if (verified?.routingId !== undefined && verified?.routingId !== null) {
        throw new Error('Failed to unassign material from routing');
      }
    } catch (error) {
      this.logger.error(
        `unassignMaterial(${plant},${materialId}) failed`,
        (error as Error).stack,
      );
      throw error;
    }
  }

  // Operations
  public async listOperations(
    routingId: number,
  ): Promise<Array<RoutingOperation>> {
    try {
      return await this.operationRepo.find({
        where: { routingId },
        relations: ['operationType'],
        order: { sequenceId: 'ASC' },
      });
    } catch (error) {
      this.logger.error(
        `listOperations(${routingId}) failed`,
        (error as Error).stack,
      );
      throw error;
    }
  }

  public async createOperation(
    dto: CreateOperationDto,
  ): Promise<RoutingOperation> {
    try {
      // Get the routing with its plant
      const current = await this.routingRepo.findOne({
        where: { routingId: dto.routingId },
      });

      if (!current) {
        throw new NotFoundException(`Routing ${dto.routingId} not found`);
      }

      const routing = await this.findOne(dto.routingId, current.plant);
      if (routing.inUse) {
        throw new BadRequestException(
          'Cannot modify operations for a routing that is in use',
        );
      }

      if (dto.operationTypeId) {
        const opType = await this.operationTypeRepo.findOne({
          where: { operationTypeId: dto.operationTypeId },
        });
        if (!opType) {
          throw new NotFoundException('Operation type not found');
        }
      }

      // If sequenceId not provided, set it to (max existing sequenceId) + 10, or 10 if none
      let { sequenceId } = dto;
      if (sequenceId === undefined || sequenceId === null) {
        const qb = this.operationRepo.createQueryBuilder('op');
        const { max } = (await qb
          .select('MAX(op.sequence_id)', 'max')
          .where('op.routing_id = :routingId', { routingId: dto.routingId })
          .getRawOne()) as { max: number | null };

        const maxSeq = max ? Number(max) : 0;
        sequenceId = maxSeq + 10;
      }

      const entity = this.operationRepo.create({ ...dto, sequenceId });
      return await this.operationRepo.save(entity);
    } catch (error) {
      this.logger.error('createOperation failed', (error as Error).stack);
      throw error;
    }
  }

  public async updateOperation(
    opId: number,
    dto: UpdateOperationDto,
  ): Promise<RoutingOperation> {
    try {
      const op = await this.operationRepo.findOne({
        where: { routingOperationId: opId },
        relations: ['routing'],
      });
      if (!op) throw new NotFoundException('Operation not found');
      if (op.routing?.inUse)
        throw new BadRequestException(
          'Cannot modify operations for a routing that is in use',
        );

      // Handle optional reorder and refresh the operation if necessary
      const refreshed = await this.handleReorderIfNeeded(op, dto);

      // Apply allowed updatable fields in a compact, type-safe way
      const updates: Partial<RoutingOperation> = {};
      if (dto.operationTypeId !== undefined)
        updates.operationTypeId = dto.operationTypeId;
      if (dto.operationName !== undefined)
        updates.operationName = dto.operationName;

      if (Object.keys(updates).length > 0) Object.assign(refreshed, updates);
      return await this.operationRepo.save(refreshed);
    } catch (error) {
      this.logger.error(
        `updateOperation(${opId}) failed`,
        (error as Error).stack,
      );
      throw error;
    }
  }

  private async handleReorderIfNeeded(
    op: RoutingOperation,
    dto: UpdateOperationDto,
  ): Promise<RoutingOperation> {
    if (dto.sequenceId === undefined || dto.sequenceId === null) return op;

    const routingId = op.routing?.routingId;
    if (!routingId) throw new BadRequestException('Operation has no routing');

    const ops = await this.listOperations(routingId);
    const other = ops
      .filter((o) => o.routingOperationId !== op.routingOperationId)
      .map((o) => o.routingOperationId);
    const pos = Math.max(1, Math.min(dto.sequenceId, other.length + 1));
    other.splice(pos - 1, 0, op.routingOperationId);
    await this.reorderOperations(routingId, other);

    const refreshed = await this.operationRepo.findOne({
      where: { routingOperationId: op.routingOperationId },
      relations: ['routing'],
    });
    if (!refreshed)
      throw new NotFoundException('Operation not found after reorder');
    return refreshed;
  }

  public async removeOperation(routingId: number, opId: number): Promise<void> {
    try {
      // First get the operation with its routing details
      const op = await this.operationRepo.findOne({
        where: { routingOperationId: opId },
        relations: ['routing'],
      });

      if (!op) {
        throw new NotFoundException(`Operation with ID ${opId} not found`);
      }

      // Delete the operation
      await this.operationRepo.delete(opId);

      // Then normalize the sequences of remaining operations
      await this.normalizeSequences(op.routingId);
    } catch (error) {
      this.logger.error(
        `removeOperation(${opId}) failed`,
        (error as Error).stack,
      );
      throw error;
    }
  }

  public async reorderOperations(
    routingId: number,
    routingOperationIds: Array<number>,
  ): Promise<Array<RoutingOperation>> {
    try {
      const ops = await this.listOperations(routingId);
      const map = new Map<number, RoutingOperation>();
      for (const o of ops) map.set(o.routingOperationId, o);

      if (routingOperationIds.length !== ops.length) {
        throw new BadRequestException(
          'Operation IDs length does not match operations count',
        );
      }

      // Validate ids
      for (const id of routingOperationIds) {
        if (!map.has(id))
          throw new BadRequestException(`Invalid operation id ${id}`);
      }

      // Build CASE expression to update id atomically and avoid unique constraint intermediate conflicts
      const cases = routingOperationIds
        .map((id, index) => `WHEN ${id} THEN ${(index + 1) * 10}`)
        .join(' ');

      const idsParameter = routingOperationIds;

      await this.operationRepo
        .createQueryBuilder()
        .update(RoutingOperation)
        .set({ sequenceId: () => `CASE routing_operation_id ${cases} END` })
        .where(
          'routing_id = :routingId AND routing_operation_id IN (:...ids)',
          {
            routingId,
            ids: idsParameter,
          },
        )
        .execute();

      // Return updated operations
      return await this.listOperations(routingId);
    } catch (error) {
      this.logger.error(
        `reorderOperations(${routingId}) failed`,
        (error as Error).stack,
      );
      throw error;
    }
  }

  /**
   * Normalize sequence ids for a routing so they are successive and increment by 10.
   * @param routingId - id of the routing whose operations sequences will be normalized
   * @returns an array of updated RoutingOperation entities with new sequenceId values
   */
  private async normalizeSequences(
    routingId: number,
  ): Promise<Array<RoutingOperation>> {
    const ops = await this.listOperations(routingId);
    const updated: Array<RoutingOperation> = ops.map((op, index) => {
      return { ...op, sequenceId: (index + 1) * 10 } as RoutingOperation;
    });
    return this.operationRepo.save(updated);
  }

  public async listOperationTypes(): Promise<Array<OperationType>> {
    try {
      return await this.operationTypeRepo.find();
    } catch (error) {
      this.logger.error('listOperationTypes failed', (error as Error).stack);
      throw error;
    }
  }

  public async getOperation(
    routingId: number,
    opId: number,
  ): Promise<RoutingOperation> {
    try {
      const operation = await this.operationRepo.findOne({
        where: {
          routingOperationId: opId,
          routingId,
        },
        relations: ['routing', 'operationType'],
      });

      if (!operation) {
        throw new NotFoundException(
          `Operation with ID ${opId} not found in routing ${routingId}`,
        );
      }

      return operation;
    } catch (error) {
      this.logger.error(
        `getOperation(routingId: ${routingId}, opId: ${opId}) failed`,
        (error as Error).stack,
      );
      throw error;
    }
  }
}

import { DatabaseType } from 'typeorm';
import { MssqlConfigurationService } from '@/config/database/mssql/abstract.mssql.config.service';
/**
 *
 * @param mssqlConfigService
 */
interface ConnectionOptions {
  encrypt: boolean;
}

interface ConnectionExtra {
  trustServerCertificate: boolean;
  authentication?: {
    type: string;
    options: {
      clientId: string;
    };
  };
}

interface BaseProperties {
  type: DatabaseType;
  host: string;
  port: number;
  database: string;
  options: ConnectionOptions;
  synchronize: boolean;
  lazy: boolean;
  autoLoadEntities: boolean;
  extra: ConnectionExtra;
  entities: Array<string>;
  migrations: Array<string>;
  migrationsTableName: string;
  requestTimeout: number;
}

interface ManagedIdentityProperties extends BaseProperties {
  extra: ConnectionExtra & {
    authentication: {
      type: string;
      options: {
        clientId: string;
      };
    };
  };
}

interface SqlAuthProperties extends BaseProperties {
  username: string;
  password: string;
}

type ConnectionProperties = ManagedIdentityProperties | SqlAuthProperties;
/**
 *
 * @param mssqlConfigService - The configuration service containing MSSQL settings.
 * @returns The connection properties for the database.
 */
export function getDatabaseConnectionProperties(
  mssqlConfigService: MssqlConfigurationService,
): ConnectionProperties {
  const baseProperties: BaseProperties = {
    autoLoadEntities: true,
    database: mssqlConfigService.database,
    entities: mssqlConfigService.entities,
    extra: {
      trustServerCertificate: true,
    },
    host: mssqlConfigService.host,
    lazy: true,
    migrations: mssqlConfigService.migrations,
    migrationsTableName: mssqlConfigService.migrationsTableName,
    options: {
      encrypt: mssqlConfigService.encrypt,
    },
    port: mssqlConfigService.port,
    requestTimeout: mssqlConfigService.requestTimeout,
    synchronize: mssqlConfigService.synchronize,
    type: mssqlConfigService.type as DatabaseType,
  };

  if (mssqlConfigService.useManagedIdentity) {
    const managedIdentityProperties: ManagedIdentityProperties = {
      ...baseProperties,
      extra: {
        ...baseProperties.extra,
        authentication: {
          options: {
            clientId: mssqlConfigService.managedIdentityClientId,
          },
          type: 'azure-active-directory-msi-vm',
        },
      },
    };

    return managedIdentityProperties;
  }

  const sqlAuthProperties: SqlAuthProperties = {
    ...baseProperties,
    password: mssqlConfigService.password,
    username: mssqlConfigService.username,
  };

  return sqlAuthProperties;
}

import { InjectDataSource } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';

export class MssqlDatabaseChecker {
  public constructor(
    @InjectDataSource()
    private dataSource: DataSource,
  ) {}

  public async pendingMigrations(): Promise<boolean> {
    if (!this.dataSource.isInitialized) {
      this.dataSource = await this.dataSource.initialize();
    }

    return this.dataSource.showMigrations();
  }

  public async waitForMigrations(
    logger: AppLogger,
    waitDelayMilliseconds: number,
    remainingRetries: number,
  ): Promise<void> {
    const isPendingMigrations: boolean = await this.pendingMigrations();
    if (isPendingMigrations && remainingRetries > 0) {
      logger.warn(
        `Waiting for Migrations to be applied (delay: ${waitDelayMilliseconds} ms, remainingRetries: ${remainingRetries})`,
      );

      await new Promise((resolve) => {
        setTimeout(resolve, waitDelayMilliseconds);
      });

      await this.waitForMigrations(
        logger,
        waitDelayMilliseconds,
        remainingRetries - 1,
      );
    } else if (remainingRetries <= 0) {
      throw new Error(`Waiting for migrations timed-out`);
    } else {
      logger.log('Migrations applied [OK]');
    }
  }
}

import { Module } from '@nestjs/common';
import { TypeOrmModule, TypeOrmModuleAsyncOptions } from '@nestjs/typeorm';
import { MssqlConfigurationService } from '@/config/database/mssql/abstract.mssql.config.service';
import { MssqlModule } from '@/config/database/mssql/mssql.module';
import { getDatabaseConnectionProperties } from '@/providers/database/mssql/mssql.connection.factory';
import { MssqlDatabaseChecker } from '@/providers/database/mssql/mssql.database.checker';

@Module({
  exports: [MssqlDatabaseChecker],
  imports: [
    TypeOrmModule.forRootAsync({
      imports: [MssqlModule],
      inject: [MssqlConfigurationService],
      useFactory: getDatabaseConnectionProperties,
    } as TypeOrmModuleAsyncOptions),
  ],
  providers: [MssqlDatabaseChecker],
})
export class MssqlDatabaseProviderModule {}

